info:
Subscribes to soundtouch/cmd/preset, resolves the UPNP ContentItem, plays it on the selected rooms, applies failure policy, and publishes per-room state.

Incoming payload:
{ "preset": 1..6, "rooms": ["living_room",...], "policy": "continue"|"strict" }

func:
const p = msg.payload || {};
const preset = parseInt(p.preset, 10);
if (!(preset >= 1 && preset <= 6)) { node.warn('bad preset: ' + p.preset); return null; }
const rooms = Array.isArray(p.rooms) ? p.rooms.filter(Boolean) : [];
if (rooms.length === 0) { node.warn('no rooms selected'); return null; }
const policy = (p.policy === 'strict') ? 'strict' : 'continue';
msg.cmd = { preset, rooms, policy };
return msg;

const fs = global.get('fs') || require('fs');
const path = '/data/presets.json';
let doc;
try { doc = JSON.parse(fs.readFileSync(path, 'utf8')); }
catch (e) { node.error('cannot read presets.json: ' + e.message, msg); return null; }
const entry = (doc.presets || []).find(p => p.preset === msg.cmd.preset);
if (!entry || !entry.content_item) {
  node.error('preset ' + msg.cmd.preset + ' not in presets.json - run rebuild library first', msg);
  return null;
}
msg.cmd.content_item_xml = entry.content_item;
msg.cmd.station_name = entry.name;
return msg;

const fs = require('fs');
let doc;
try { doc = JSON.parse(fs.readFileSync('/data/rooms.json', 'utf8')); }
catch (e) { node.error('cannot read rooms.json: ' + e.message, msg); return null; }
const byId = Object.fromEntries((doc.rooms || []).map(r => [r.id, r]));
const selected = msg.cmd.rooms.map(id => byId[id]).filter(Boolean);
if (selected.length === 0) { node.error('no known rooms in selection', msg); return null; }
// Prefer mains-powered as master; portables drop the zone when sleeping.
selected.sort((a, b) => (a.role === 'mains' ? -1 : 1) - (b.role === 'mains' ? -1 : 1));
msg.cmd.master = selected[0];
msg.cmd.slaves = selected.slice(1);
return msg;

const m = msg.cmd.master;
msg.url = `http://${m.host}:${m.port}/select`;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/xml' };
msg.payload = msg.cmd.content_item_xml;
msg.room = m.id;
msg.step = 'select_master';
return msg;

const ok = (msg.statusCode >= 200 && msg.statusCode < 300) && !/error/i.test(String(msg.payload || ''));
msg.results = msg.results || [];
msg.results.push({ room: msg.cmd.master.id, role: 'master', ok, raw: msg.payload, status: msg.statusCode });
if (!ok && msg.cmd.policy === 'strict') {
  msg.abort = true;
}
return msg;

const m = msg.cmd.master;
// MAC is required by SoundTouch zone API. Each room must have 'mac' filled in rooms.json (auto-populated by state polling).
if (!m.mac) {
  node.warn('master ' + m.id + ' has no MAC yet - state polling needs to run once');
  return null;
}
const slaves = msg.cmd.slaves.filter(s => s.mac);
const slaveXml = slaves.map(s => `<member ipaddress="${s.host}">${s.mac}</member>`).join('');
msg.url = `http://${m.host}:${m.port}/setZone`;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/xml' };
msg.payload = `<zone master="${m.mac}">${slaveXml}</zone>`;
return msg;

const ok = (msg.statusCode >= 200 && msg.statusCode < 300) && !/error/i.test(String(msg.payload || ''));
for (const s of msg.cmd.slaves) {
  msg.results.push({ room: s.id, role: 'slave', ok, raw: msg.payload, status: msg.statusCode });
}
return msg;

const failed = msg.results.filter(r => !r.ok);
if (msg.cmd.policy === 'strict' && failed.length > 0) {
  // Roll back: power off rooms that succeeded.
  const fs = require('fs');
  const rooms = JSON.parse(fs.readFileSync('/data/rooms.json', 'utf8')).rooms;
  const byId = Object.fromEntries(rooms.map(r => [r.id, r]));
  const succeeded = msg.results.filter(r => r.ok).map(r => byId[r.room]).filter(Boolean);
  msg.rollback = succeeded;
}
msg.summary = { preset: msg.cmd.preset, rooms: msg.cmd.rooms, policy: msg.cmd.policy, ok: failed.length === 0, failed };
return msg;

// Per-room state.
const out = (msg.results || []).map(r => ({
  topic: 'soundtouch/state/' + r.room,
  payload: { ok: r.ok, preset: msg.cmd.preset, station: msg.cmd.station_name, role: r.role, ts: Date.now() }
}));
// Plus a summary.
out.push({ topic: 'soundtouch/state/last_command', payload: msg.summary || { preset: msg.cmd.preset, rooms: msg.cmd.rooms } });
return [out];

const fs = require('fs');
let cfg;
try { cfg = JSON.parse(fs.readFileSync('/data/radio-stations.json', 'utf8')); }
catch (e) {
  node.error('cannot read /data/radio-stations.json - check the bind mount in docker-compose.yml: ' + e.message, msg);
  return null;
}
msg.stations = cfg.stations || [];
msg.defaults = cfg.defaults || {};
return msg;

const cached = flow.get('rb_server');
const until = flow.get('rb_server_until') || 0;
if (cached && Date.now() < until) {
  msg.rb_base = cached;
  return [null, msg];
}
msg.url = 'https://all.api.radio-browser.info/json/servers';
msg.method = 'GET';
msg.headers = { 'User-Agent': env.get('RB_USER_AGENT') || 'SoundTouchReplacement/0.1' };
return [msg, null];

const list = (msg.payload || []).filter(s => s.name).map(s => 'https://' + s.name);
if (list.length === 0) { node.error('no Radio Browser servers returned', msg); return null; }
const pick = list[Math.floor(Math.random() * list.length)];
flow.set('rb_server', pick);
flow.set('rb_server_until', Date.now() + 24 * 3600 * 1000);
msg.rb_base = pick;
return msg;

const s = msg.payload;
const base = msg.rb_base;
const defaults = msg.defaults || {};
const ua = env.get('RB_USER_AGENT') || 'SoundTouchReplacement/0.1';
msg.headers = { 'User-Agent': ua };
msg.method = 'GET';
msg.station_meta = s;
if (s.pinned_uuid) {
  msg.url = `${base}/json/stations/byuuid/${encodeURIComponent(s.pinned_uuid)}`;
} else {
  const q = new URLSearchParams();
  if (s.rb_search && s.rb_search.name) q.set('name', s.rb_search.name);
  if (s.rb_search && s.rb_search.language) q.set('language', s.rb_search.language);
  if (s.rb_search && s.rb_search.state) q.set('state', s.rb_search.state);
  q.set('countrycode', (s.rb_search && s.rb_search.countrycode) || defaults.countrycode || 'BE');
  q.set('hidebroken', 'true');
  q.set('order', 'clickcount');
  q.set('reverse', 'true');
  q.set('limit', '20');
  msg.url = `${base}/json/stations/search?${q.toString()}`;
}
return msg;

const arr = Array.isArray(msg.payload) ? msg.payload : (msg.payload ? [msg.payload] : []);
if (arr.length === 0) { node.warn('no RB hits for ' + msg.station_meta.name); return null; }
const defaults = msg.defaults || {};
const geo = defaults.geo || { lat: 50.9307, lon: 5.3325 };
function dist(a, b) { const dx = a.lat - b.lat, dy = a.lon - b.lon; return Math.sqrt(dx*dx + dy*dy); }
const withGeo = arr.filter(x => x.geo_lat && x.geo_long);
const pool = withGeo.length ? withGeo : arr;
pool.sort((a, b) => {
  if (a.geo_lat && b.geo_lat) return dist({lat:+a.geo_lat,lon:+a.geo_long}, geo) - dist({lat:+b.geo_lat,lon:+b.geo_long}, geo);
  return (b.clickcount || 0) - (a.clickcount || 0);
});
const pick = pool[0];
msg.station_resolved = {
  name: msg.station_meta.name,
  preset: msg.station_meta.preset,
  uuid: pick.stationuuid,
  url: pick.url_resolved || pick.url,
  homepage: pick.homepage,
  favicon: pick.favicon
};
// Fire click endpoint to get final stream URL (handles redirects).
msg.url = `${msg.rb_base}/json/url/${encodeURIComponent(pick.stationuuid)}`;
msg.method = 'GET';
return msg;

const click = msg.payload || {};
if (click.url) msg.station_resolved.url = click.url;
const gerbera = env.get('GERBERA_URL') || 'http://gerbera-host:49152';
const item = msg.station_resolved;
// Gerbera external-URL item creation. The exact REST shape depends on the
// Gerbera version - this is the documented add_object call.
msg.url = `${gerbera}/content/interface?req_type=add_object&sid=auto`;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
const body = new URLSearchParams();
body.set('parent_id', '0');
body.set('obj_type', 'item');
body.set('class', 'object.item.audioItem.audioBroadcast');
body.set('title', item.name);
body.set('location', item.url);
body.set('protocol', 'http-get');
body.set('mime-type', 'audio/mpeg');
msg.payload = body.toString();
return msg;

// Parse object_id from Gerbera response (format varies; here we assume a numeric id appears).
const body = String(msg.payload || '');
const m = body.match(/object_id\s*[:=]\s*\"?(\d+)/);
const objectId = m ? m[1] : null;
const item = msg.station_resolved;
// The UPNP location format the SoundTouch expects is the DLNA item URL exposed by Gerbera.
// Conservative form: http://<pi-ip>:49152/content/media/object_id/<id>/res_id/0/ext/file.mp3
// We store the resolved stream URL too as a fallback.
msg.entry = {
  preset: item.preset,
  name: item.name,
  rb_uuid: item.uuid,
  stream_url: item.url,
  gerbera_object_id: objectId,
  content_item: `<ContentItem source=\"UPNP\" location=\"${item.url}\" sourceAccount=\"\" isPresetable=\"true\"><itemName>${item.name}</itemName></ContentItem>`
};
return msg;

const fs = require('fs');
const out = { generated_at: new Date().toISOString(), presets: msg.payload };
fs.writeFileSync('/data/presets.json', JSON.stringify(out, null, 2));
msg.payload = { ok: true, count: out.presets.length };
msg.topic = 'soundtouch/state/library';
return msg;

const fs = require('fs');
const presets = JSON.parse(fs.readFileSync('/data/presets.json', 'utf8')).presets || [];
const rooms = JSON.parse(fs.readFileSync('/data/rooms.json', 'utf8')).rooms || [];
if (presets.length === 0) { node.error('presets.json empty - run rebuild library first', msg); return null; }
// Push to every room; the IR remote on each device should map to the same stations.
const out = [];
for (const room of rooms) {
  for (const p of presets) {
    out.push({ room, preset: p });
  }
}
return [out.map(x => ({ payload: x }))];

const room = msg.payload.room;
const seen = flow.get('backed_up') || {};
if (seen[room.id]) return msg;
seen[room.id] = true;
flow.set('backed_up', seen);
msg.url = `http://${room.host}:${room.port}/presets`;
msg.method = 'GET';
msg.do_backup = true;
return msg;

const fs = require('fs');
const ts = new Date().toISOString().replace(/[:.]/g, '-');
const path = `/data/presets-backup-${msg.payload.cmd?.room?.id || 'device'}-${ts}.xml`;
// fall back: use the original room from upstream message
const room = msg.req && msg.req.url ? null : null;
fs.writeFileSync(path, msg.payload || '');
node.log('wrote backup ' + path);
msg.do_backup = false;
return msg;

const { room, preset } = msg.payload;
msg.url = `http://${room.host}:${room.port}/setPresetButton`;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/xml' };
msg.payload = `<preset id=\"${preset.preset}\">${preset.content_item}</preset>`;
return msg;

const fs = require('fs');
const rooms = JSON.parse(fs.readFileSync('/data/rooms.json', 'utf8')).rooms || [];
return [rooms.map(r => ({ payload: r, url: `http://${r.host}:${r.port}/now_playing`, method: 'GET', _room: r }))];

const room = msg._room;
const body = String(msg.payload || '');
const src = (body.match(/source=\"([^\"]+)\"/) || [])[1] || null;
const name = (body.match(/<itemName>([^<]+)<\/itemName>/) || [])[1] || null;
const mac = (body.match(/deviceID=\"([^\"]+)\"/) || [])[1] || null;
// Persist MAC into rooms.json (used by /setZone).
if (mac && !room.mac) {
  const fs = require('fs');
  const doc = JSON.parse(fs.readFileSync('/data/rooms.json', 'utf8'));
  const r = (doc.rooms || []).find(x => x.id === room.id);
  if (r) { r.mac = mac; fs.writeFileSync('/data/rooms.json', JSON.stringify(doc, null, 2)); }
}
msg.topic = 'soundtouch/state/' + room.id + '/now_playing';
msg.payload = { source: src, item: name, mac, ok: msg.statusCode === 200, ts: Date.now() };
return msg;
